@@ -1,12 +1,26 @@
 /* SPDX-License-Identifier: Apache-2.0
- * Spec-site chrome on top of the shared token palette (flatbars-tokens.css, the
- * single source generated by `npm run gen:tokens`). Maps the FlatBars violet
- * accent onto Starlight's theme variables so the spec matches the design system.
+ * Spec-site chrome on top of the shared design system (flatbars-chrome.css +
+ * flatbars-tokens.css, both single-sourced and loaded via customCss). This maps
+ * Starlight's theme variables onto the shared chrome tokens, so the spec reads
+ * with the SAME palette and background as the tutorials and the Lab — light and
+ * dark both flip with the one [data-theme] the shared topbar toggles.
  */
 :root {
-  --sl-color-accent-low: var(--c-violet-tint, #2a1f3d);
-  --sl-color-accent: var(--c-violet, #8b5cf6);
-  --sl-color-accent-high: var(--c-violet-bright, #c4b5fd);
+  /* Background + surfaces → the shared chrome (especially the dark bg, #16141d). */
+  --sl-color-bg: var(--bg);
+  --sl-color-bg-nav: var(--bg);
+  --sl-color-bg-sidebar: var(--bg-1);
+  --sl-color-bg-inline-code: var(--bg-2);
+  /* Text + borders. */
+  --sl-color-text: var(--fg);
+  --sl-color-text-accent: var(--accent);
+  --sl-color-hairline: var(--border);
+  --sl-color-hairline-shade: var(--border);
+  --sl-color-hairline-light: var(--border);
+  /* Accent scale → the unified violet. */
+  --sl-color-accent-low: var(--accent-softer);
+  --sl-color-accent: var(--accent);
+  --sl-color-accent-high: var(--accent-2);
   /* Match Starlight's reserved nav band to the shared topbar's 52px height, so
      the sidebar/TOC `top` offsets and the content padding line up with it. */
   --sl-nav-height: 3.25rem;

